import{_ as l,c as r,o as i,a0 as o}from"./chunks/framework.oTSD2LDJ.js";const g=JSON.parse('{"title":"组件百科概览","description":"","frontmatter":{"title":"组件百科概览","layout":"doc","editLink":true},"headers":[],"relativePath":"components-wiki/overview.md","filePath":"zh/components-wiki/overview.md"}'),a={name:"components-wiki/overview.md"};function e(d,t,n,s,h,c){return i(),r("div",null,t[0]||(t[0]=[o('<h1 id="组件百科概览" tabindex="-1">组件百科概览 <a class="header-anchor" href="#组件百科概览" aria-label="Permalink to &quot;组件百科概览&quot;">​</a></h1><p>欢迎使用 Uniquenium！本指南将带你了解 Uniquenium 的核心功能和基本操作方法。</p><h2 id="界面介绍" tabindex="-1">界面介绍 <a class="header-anchor" href="#界面介绍" aria-label="Permalink to &quot;界面介绍&quot;">​</a></h2><p>Uniquenium 的主界面主要由以下几部分组成：</p><h3 id="托盘区" tabindex="-1">托盘区 <a class="header-anchor" href="#托盘区" aria-label="Permalink to &quot;托盘区&quot;">​</a></h3><p>程序启动后，默认最小化到系统托盘区（任务栏右下角）：</p><ul><li><strong>左键单击</strong>：显示/隐藏主面板</li><li><strong>右键单击</strong>：打开托盘菜单，包含： <ul><li>显示主面板</li><li>页面管理</li><li>设置</li><li>插件管理</li><li>退出程序</li></ul></li></ul><h3 id="主面板" tabindex="-1">主面板 <a class="header-anchor" href="#主面板" aria-label="Permalink to &quot;主面板&quot;">​</a></h3><p>主面板是 Uniquenium 的核心操作区域，分为：</p><ol><li><strong>左侧导航栏</strong>：页面列表，新建/删除/切换页面</li><li><strong>中间工作区</strong>：页面画布，组件的显示和编辑区域</li><li><strong>右侧属性面板</strong>：选中组件时显示属性编辑选项（编辑模式）</li></ol><h3 id="编辑模式-vs-浏览模式" tabindex="-1">编辑模式 vs 浏览模式 <a class="header-anchor" href="#编辑模式-vs-浏览模式" aria-label="Permalink to &quot;编辑模式 vs 浏览模式&quot;">​</a></h3><p>Uniquenium 有两种运行模式：</p><ul><li>🖊️ <strong>编辑模式</strong>：可以添加、删除、拖拽组件，调整属性</li><li>👁️ <strong>浏览模式</strong>：组件显示正常，但不可修改（日常使用状态）</li></ul><p>通过顶部工具栏的「编辑/浏览」切换按钮，或按快捷键 <code>Ctrl + E</code> 切换。</p><hr><h2 id="创建页面" tabindex="-1">创建页面 <a class="header-anchor" href="#创建页面" aria-label="Permalink to &quot;创建页面&quot;">​</a></h2><p>页面是 Uniquenium 组织组件的容器，你可以创建多个独立页面，例如：</p><ul><li>主面板：放时钟、天气、快捷启动</li><li>监控面板：放 CPU/内存/网络 监控图表</li><li>工作面板：放待办事项、便签</li></ul><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>打开主面板，确保处于<strong>编辑模式</strong></li><li>点击左侧导航栏顶部的 <strong>「+ 新建页面」</strong> 按钮</li><li>在弹出的对话框中输入页面名称（例如：「我的主页」）</li><li>选择页面样式： <ul><li><strong>普通面板</strong>：固定大小的窗口面板</li><li><strong>全屏遮罩</strong>：覆盖整个屏幕的半透明层</li><li><strong>无边框面板</strong>：可自由缩放大小</li></ul></li><li>点击「确定」完成创建</li></ol><h3 id="页面管理" tabindex="-1">页面管理 <a class="header-anchor" href="#页面管理" aria-label="Permalink to &quot;页面管理&quot;">​</a></h3><ul><li><strong>切换页面</strong>：点击左侧导航栏中的页面名称</li><li><strong>重命名页面</strong>：右键页面 → 重命名</li><li><strong>删除页面</strong>：右键页面 → 删除（⚠️ 删除后页面内所有组件也会被删除）</li><li><strong>复制页面</strong>：右键页面 → 复制为新页面</li><li><strong>导出模板</strong>：右键页面 → 导出为模板（分享或备份）</li><li><strong>页面排序</strong>：在导航栏中直接拖拽调整顺序</li></ul><hr><h2 id="添加组件" tabindex="-1">添加组件 <a class="header-anchor" href="#添加组件" aria-label="Permalink to &quot;添加组件&quot;">​</a></h2><p>Uniquenium 提供了多种内置组件，通过插件系统还可以扩展更多。</p><h3 id="添加步骤" tabindex="-1">添加步骤 <a class="header-anchor" href="#添加步骤" aria-label="Permalink to &quot;添加步骤&quot;">​</a></h3><ol><li>确保处于<strong>编辑模式</strong></li><li>点击工具栏中的 <strong>「添加组件」</strong> 按钮（或按快捷键 <code>Ctrl + Shift + A</code>）</li><li>在组件选择窗口中，从左侧分类选择组件类型： <ul><li><strong>基础</strong>：文字、图片、按钮、图标</li><li><strong>输入</strong>：文本框、复选框、下拉选择</li><li><strong>容器</strong>：框架、选项卡</li><li><strong>显示</strong>：图表、进度条、提示框</li><li><strong>窗口</strong>：对话框、消息框</li><li><strong>自定义</strong>：插件提供的组件</li></ul></li><li>点击或拖拽组件到工作区即可添加</li></ol><h3 id="常用组件推荐" tabindex="-1">常用组件推荐 <a class="header-anchor" href="#常用组件推荐" aria-label="Permalink to &quot;常用组件推荐&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>用途</th><th>示例场景</th></tr></thead><tbody><tr><td>UniDeskText</td><td>显示文字</td><td>时钟标题、便签内容</td></tr><tr><td>UniDeskImage</td><td>显示图片</td><td>头像、照片墙、Logo</td></tr><tr><td>UniDeskButton</td><td>点击按钮</td><td>快捷启动、功能开关</td></tr><tr><td>UniDeskFrame</td><td>分组容器</td><td>将多个组件框在一起</td></tr><tr><td>UniDeskChart</td><td>数据图表</td><td>CPU/内存使用率监控</td></tr><tr><td>UniDeskTextField</td><td>文本输入</td><td>待办事项输入框</td></tr><tr><td>UniDeskIcon</td><td>图标显示</td><td>功能图标、状态指示</td></tr></tbody></table><hr><h2 id="组件属性编辑" tabindex="-1">组件属性编辑 <a class="header-anchor" href="#组件属性编辑" aria-label="Permalink to &quot;组件属性编辑&quot;">​</a></h2><p>选中组件后，右侧属性面板会显示该组件可编辑的属性。</p><h3 id="基础操作" tabindex="-1">基础操作 <a class="header-anchor" href="#基础操作" aria-label="Permalink to &quot;基础操作&quot;">​</a></h3><h4 id="选中组件" tabindex="-1">选中组件 <a class="header-anchor" href="#选中组件" aria-label="Permalink to &quot;选中组件&quot;">​</a></h4><ul><li><strong>点击</strong>工作区中的组件即可选中（显示蓝色边框）</li><li><strong>多选</strong>：按住 <code>Shift</code> 依次点击，或拖拽框选多个组件</li><li><strong>全选</strong>：<code>Ctrl + A</code></li><li><strong>取消选中</strong>：点击空白处或按 <code>Esc</code></li></ul><h4 id="移动与缩放" tabindex="-1">移动与缩放 <a class="header-anchor" href="#移动与缩放" aria-label="Permalink to &quot;移动与缩放&quot;">​</a></h4><ul><li><strong>移动</strong>：直接拖拽组件到目标位置</li><li><strong>精确移动</strong>：选中后用方向键微调（1像素），按住 <code>Shift</code> + 方向键每次移动 10 像素</li><li><strong>缩放</strong>：选中组件后拖拽边缘或角上的控制点</li><li><strong>保持比例缩放</strong>：按住 <code>Shift</code> 拖拽角控制点</li></ul><h4 id="复制与删除" tabindex="-1">复制与删除 <a class="header-anchor" href="#复制与删除" aria-label="Permalink to &quot;复制与删除&quot;">​</a></h4><ul><li><strong>复制</strong>：选中后按 <code>Ctrl + C</code>，再按 <code>Ctrl + V</code> 粘贴；或右键 → 复制</li><li><strong>剪切</strong>：<code>Ctrl + X</code></li><li><strong>删除</strong>：按 <code>Delete</code> 键；或右键 → 删除</li></ul><h3 id="通用属性" tabindex="-1">通用属性 <a class="header-anchor" href="#通用属性" aria-label="Permalink to &quot;通用属性&quot;">​</a></h3><p>所有组件都具备的通用属性：</p><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>示例值</th></tr></thead><tbody><tr><td>X / Y</td><td>组件左上角坐标（像素）</td><td>X: 100, Y: 50</td></tr><tr><td>宽度 / 高度</td><td>组件尺寸（像素）</td><td>W: 200, H: 100</td></tr><tr><td>不透明度</td><td>0（完全透明）~ 1（完全不透明）</td><td>0.85</td></tr><tr><td>可见性</td><td>是否显示该组件</td><td>true / false</td></tr><tr><td>Z 坐标</td><td>组件叠放顺序，值越大越靠上</td><td>0, 1, 2...</td></tr><tr><td>组件ID</td><td>唯一标识符，用于脚本引用</td><td>myButton_001</td></tr></tbody></table><h3 id="层级调整" tabindex="-1">层级调整 <a class="header-anchor" href="#层级调整" aria-label="Permalink to &quot;层级调整&quot;">​</a></h3><p>组件的层级（Z 轴）决定了重叠时谁显示在上面：</p><ul><li>右键组件 → <strong>置于顶层</strong>（Z 值设为最大）</li><li>右键组件 → <strong>置于底层</strong>（Z 值设为最小）</li><li>右键组件 → <strong>上移一层</strong>（Z 值 +1）</li><li>右键组件 → <strong>下移一层</strong>（Z 值 -1）</li><li>在左侧「组件树」面板中直接拖拽调整顺序</li></ul><h3 id="对齐与分布" tabindex="-1">对齐与分布 <a class="header-anchor" href="#对齐与分布" aria-label="Permalink to &quot;对齐与分布&quot;">​</a></h3><p>选中多个组件后，可使用工具栏对齐按钮：</p><ul><li>⬅️ 左对齐 / ➡️ 右对齐 / ↕️ 垂直居中</li><li>⬆️ 顶端对齐 / ⬇️ 底端对齐 / ↔️ 水平居中</li><li>↔️ 水平等间距 / ↕️ 垂直等间距</li><li>等宽 / 等高 / 等尺寸</li></ul><hr><h2 id="快捷键设置" tabindex="-1">快捷键设置 <a class="header-anchor" href="#快捷键设置" aria-label="Permalink to &quot;快捷键设置&quot;">​</a></h2><p>合理使用快捷键可以大幅提升操作效率。Uniquenium 支持丰富的全局热键绑定。</p><h3 id="默认快捷键" tabindex="-1">默认快捷键 <a class="header-anchor" href="#默认快捷键" aria-label="Permalink to &quot;默认快捷键&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl + Alt + U</code></td><td>显示/隐藏主面板</td></tr><tr><td><code>Ctrl + Alt + S</code></td><td>打开设置窗口</td></tr><tr><td><code>Ctrl + E</code></td><td>切换编辑/浏览模式</td></tr><tr><td><code>Ctrl + Shift + A</code></td><td>添加新组件</td></tr><tr><td><code>Ctrl + N</code></td><td>新建页面</td></tr><tr><td><code>Ctrl + S</code></td><td>保存当前页面</td></tr><tr><td><code>Ctrl + Z</code></td><td>撤销上一步操作</td></tr><tr><td><code>Ctrl + Shift + Z</code></td><td>重做操作</td></tr><tr><td><code>Delete</code></td><td>删除选中组件</td></tr><tr><td><code>Ctrl + D</code></td><td>快速复制选中组件</td></tr></tbody></table><h3 id="自定义快捷键" tabindex="-1">自定义快捷键 <a class="header-anchor" href="#自定义快捷键" aria-label="Permalink to &quot;自定义快捷键&quot;">​</a></h3><ol><li>打开 <strong>设置</strong> → <strong>快捷键</strong> 选项卡</li><li>找到要修改的功能，点击快捷键输入框</li><li>按下你想要的新组合键（例如：<code>Ctrl + Alt + H</code>）</li><li>如果提示「已被占用」，请选择其他组合键</li><li>点击「应用」保存设置</li></ol><div class="tip custom-block"><p class="custom-block-title">小技巧</p><ul><li>推荐使用 <code>Ctrl + Alt + 字母</code> 或 <code>Win + Shift + 字母</code> 作为全局热键，冲突较少</li><li>数字小键盘的按键也可以绑定，适合频繁操作的功能</li></ul></div><h3 id="快捷键冲突处理" tabindex="-1">快捷键冲突处理 <a class="header-anchor" href="#快捷键冲突处理" aria-label="Permalink to &quot;快捷键冲突处理&quot;">​</a></h3><p>如果设置的快捷键不生效：</p><ol><li>检查是否被其他软件占用（QQ、微信、输入法、浏览器常用 <code>Alt + 字母</code>）</li><li>尝试以<strong>管理员身份</strong>运行 Uniquenium（部分系统热键需要更高权限）</li><li>修改为一个不常用的组合键，例如 <code>Ctrl + Shift + F12</code></li></ol><hr><h2 id="主题切换" tabindex="-1">主题切换 <a class="header-anchor" href="#主题切换" aria-label="Permalink to &quot;主题切换&quot;">​</a></h2><p>Uniquenium 支持三种主题模式，完美搭配你的 Windows 外观。</p><h3 id="切换方式" tabindex="-1">切换方式 <a class="header-anchor" href="#切换方式" aria-label="Permalink to &quot;切换方式&quot;">​</a></h3><ol><li>打开 <strong>设置</strong> → <strong>外观</strong> 选项卡</li><li>在「主题模式」中选择： <ul><li>🌓 <strong>跟随系统</strong>（推荐）：自动同步 Windows 的深色/浅色设置</li><li>☀️ <strong>浅色模式</strong>：清新明亮的白色界面</li><li>🌙 <strong>深色模式</strong>：护眼省电的黑色界面</li></ul></li><li>点击「应用」立即生效，无需重启</li></ol><h3 id="主题色设置" tabindex="-1">主题色设置 <a class="header-anchor" href="#主题色设置" aria-label="Permalink to &quot;主题色设置&quot;">​</a></h3><p>除了深浅模式，你还可以自定义强调色（主色调）：</p><ul><li>在「外观」选项卡中点击「主题色」</li><li>选择预设颜色，或点击「自定义颜色」使用拾色器</li><li>所有按钮、高亮、选中框都会自动使用该颜色</li></ul><h3 id="亚克力效果" tabindex="-1">亚克力效果 <a class="header-anchor" href="#亚克力效果" aria-label="Permalink to &quot;亚克力效果&quot;">​</a></h3><p>UniDesk 控件库支持 <strong>Acrylic 亚克力</strong> 模糊效果（类似 Windows 11 的 Mica 材质）：</p><ul><li><strong>启用位置</strong>：设置 → 外观 → 启用亚克力效果</li><li><strong>模糊强度</strong>：调整滑块，值越大背景越模糊（0-100）</li><li><strong>色彩浓度</strong>：调整面板颜色的不透明度</li></ul><div class="warning custom-block"><p class="custom-block-title">性能提示</p><p>亚克力效果会消耗 GPU 资源，如果电脑配置较低或使用电池供电，建议关闭以节省电量。</p></div><hr><h2 id="更多功能" tabindex="-1">更多功能 <a class="header-anchor" href="#更多功能" aria-label="Permalink to &quot;更多功能&quot;">​</a></h2><ul><li>🎨 <strong>自定义壁纸</strong>：设置 → 外观 → 壁纸，支持本地图片、多图轮播、网络 API</li><li>🖱️ <strong>自定义光标</strong>：参考 <a href="/custom-developing/cursor-style">自定义光标样式</a></li><li>📦 <strong>模板系统</strong>：参考 <a href="/custom-developing/template">模板使用指南</a></li><li>🔌 <strong>插件扩展</strong>：参考 <a href="/custom-developing/plugin">插件开发指南</a></li><li>📚 <strong>控件开发</strong>：参考 <a href="/controls-reference/overview">UniDesk 控件库概览</a></li></ul><p>有问题？查看 <a href="/faq">常见问题 FAQ</a> 或 <a href="https://github.com/Uniquenium/Uniquenium/issues" target="_blank" rel="noreferrer">提交 Issue</a>。</p>',75)]))}const b=l(a,[["render",e]]);export{g as __pageData,b as default};
